/* Egyptian book — Pediatrics; Accepted sources only. */
window.__SHB_EGYPTIAN_BOOK_QUESTIONS__=(window.__SHB_EGYPTIAN_BOOK_QUESTIONS__||[]).concat([{"id":"EB-paediatrics-neonatology-accepted-Q2","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Complications","q":"ComplicationsseenamongSGAbaby,except","o":["Hypoglycaemia","Hypothermia","Polycythemia","Anaemia"],"ol":["A","B","C","D"],"k":3,"ex":"SGA infants are at increased risk of hypoglycemia, hypothermia and polycythemia, reflecting reduced glycogen/fat stores, impaired thermoregulation and chronic intrauterine hypoxia. Anemia is not the classic immediate metabolic complication listed in this group, so it is the intended exception.","more":"SGA infants are at increased risk of hypoglycemia, hypothermia and polycythemia, reflecting reduced glycogen/fat stores, impaired thermoregulation and chronic intrauterine hypoxia. Anemia is not the classic immediate metabolic complication listed in this group, so it is the intended exception.\n\nCurriculum alignment: Neonatology 2024–25, pp.22–24: SGA/IUGR complications.\n\nHigh-yield point: SGA infants need early temperature monitoring, feeding support and glucose surveillance.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q2 — Complication of SGA: exception","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 70 · printed page 122 · answer-key page 82 · original question 2.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q4","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Complications","q":"ComplicationoftheLGAbabies,except","o":["Hypoglycemia","Birthinjury","Hyperglycemia","Noneoftheabove"],"ol":["A","B","C","D"],"k":2,"ex":"LGA infants, especially infants of diabetic mothers, are at risk of birth trauma, shoulder dystocia, hypoglycemia and respiratory/metabolic problems. Hyperglycemia is not the expected early neonatal complication; hypoglycemia is typical because fetal insulin remains high after placental glucose supply stops.","more":"LGA infants, especially infants of diabetic mothers, are at risk of birth trauma, shoulder dystocia, hypoglycemia and respiratory/metabolic problems. Hyperglycemia is not the expected early neonatal complication; hypoglycemia is typical because fetal insulin remains high after placental glucose supply stops.\n\nCurriculum alignment: Neonatology 2024–25, pp.38–42: infant of diabetic mother and birth injury.\n\nHigh-yield point: An infant of a diabetic mother requires early glucose monitoring even when clinically well.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q4 — Complication of an LGA infant: exception","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 70 · printed page 122 · answer-key page 82 · original question 4.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q8","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Anatomy","q":"Theumbilicalcordcontains","o":["Arteryandonevein","Onearteryandtwocapillary","Twoveinsandoneartery","Twoarteriesandonevein"],"ol":["A","B","C","D"],"k":3,"ex":"A normal umbilical cord contains two umbilical arteries and one umbilical vein. The vein carries oxygenated blood from placenta to fetus; the arteries carry deoxygenated blood from fetus to placenta.","more":"A normal umbilical cord contains two umbilical arteries and one umbilical vein. The vein carries oxygenated blood from placenta to fetus; the arteries carry deoxygenated blood from fetus to placenta.\n\nCurriculum alignment: Neonatology 2024–25, p.7: umbilical cord has two arteries and one vein.\n\nHigh-yield point: A single umbilical artery can be associated with congenital anomalies and warrants careful assessment.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q8 — Normal umbilical cord vessel count","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 70 · printed page 122 · answer-key page 82 · original question 8.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q14","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Thecharacteristicofthecephalhaematoma,except","o":["Subperiosteal","Boundedbymarginofbone","Resolvesby48hours","Softtissueswelling"],"ol":["A","B","C","D"],"k":2,"ex":"Cephalohematoma is a subperiosteal collection of blood, so it is limited by cranial suture lines and does not cross them. It may become more apparent over hours after birth and usually resolves over weeks, not 48 hours. The description “soft tissue swelling” is less specific than the defining subperiosteal location.","more":"Cephalohematoma is a subperiosteal collection of blood, so it is limited by cranial suture lines and does not cross them. It may become more apparent over hours after birth and usually resolves over weeks, not 48 hours. The description “soft tissue swelling” is less specific than the defining subperiosteal location.\n\nCurriculum alignment: Neonatology 2024–25, pp.40–42: birth injuries and scalp swellings.\n\nHigh-yield point: Cephalohematoma does not cross sutures; caput succedaneum is diffuse edema that crosses sutures.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q14 — Cephalohematoma: feature that is not characteristic","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 71 · printed page 123 · answer-key page 82 · original question 14.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q21","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Nutrition","q":"Thehumanmilkcontainsproteins","o":["1.1g%","2.1g%","3.1g%","4.1g%"],"ol":["A","B","C","D"],"k":0,"ex":"Mature human milk contains approximately 0.9–1.2 g protein per 100 mL, with higher protein concentration in colostrum and lower levels later in lactation. The source option 1.1 g% is a reasonable approximate value.","more":"Mature human milk contains approximately 0.9–1.2 g protein per 100 mL, with higher protein concentration in colostrum and lower levels later in lactation. The source option 1.1 g% is a reasonable approximate value.\n\nCurriculum alignment: Growth and Nutrition 2024, pp.30–32: breast-milk composition; Neonatology 2024–25, p.21: feeding and nutrition.\n\nHigh-yield point: Human milk protein concentration changes over lactation and is not a fixed value.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q21 — Approximate protein concentration of human milk","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 71 · printed page 123 · answer-key page 82 · original question 21.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q27","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Apneaischaracterizedbyfollowing,except","o":["Ceasationofrespirationfor30seconds","Tachycardia","Bradycardia","Cyanosis"],"ol":["A","B","C","D"],"k":1,"ex":"Neonatal apnea is a cessation of breathing for about 20 seconds or longer, or a shorter pause associated with bradycardia, cyanosis or desaturation. Tachycardia is not the characteristic associated cardiovascular response; bradycardia is typical.","more":"Neonatal apnea is a cessation of breathing for about 20 seconds or longer, or a shorter pause associated with bradycardia, cyanosis or desaturation. Tachycardia is not the characteristic associated cardiovascular response; bradycardia is typical.\n\nCurriculum alignment: Neonatology 2024–25, p.37: apnea definition and types.\n\nHigh-yield point: Apnea of prematurity is a diagnosis of exclusion; assess for infection, metabolic disturbance, respiratory disease and CNS causes. [AAP apnea of prematurity](https://publications.aap.org/pediatrics/article/137/1/e20153757/52845/Apnea-of-Prematurity).","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q27 — Neonatal apnea: feature that is not typical","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 71 · printed page 123 · answer-key page 82 · original question 27.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q35","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Theunconjugatedbilirubintoxictobrain","o":["Albuminbound","Free","Both","None"],"ol":["A","B","C","D"],"k":1,"ex":"Unbound unconjugated bilirubin can cross the blood–brain barrier and deposit in vulnerable brain regions. Bilirubin bound tightly to albumin is much less available to enter the brain. Low albumin, prematurity, acidosis, sepsis and clinical instability increase neurotoxicity risk.","more":"Unbound unconjugated bilirubin can cross the blood–brain barrier and deposit in vulnerable brain regions. Bilirubin bound tightly to albumin is much less available to enter the brain. Low albumin, prematurity, acidosis, sepsis and clinical instability increase neurotoxicity risk.\n\nCurriculum alignment: Neonatology 2024–25, pp.43–51: unconjugated bilirubin, risk factors and kernicterus. AAP 2022 guideline: low albumin, gestational age, hemolysis, sepsis and instability alter neurotoxicity risk. [AAP hyperbilirubinemia guideline](https://publications.aap.org/pediatrics/article/150/3/e2022058859/188549/).\n\nHigh-yield point: It is the unbound/unconjugated fraction that is most relevant to bilirubin neurotoxicity.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q35 — Bilirubin fraction that is neurotoxic in kernicterus","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 72 · printed page 124 · answer-key page 82 · original question 35.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q37","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Treatment","q":"Themodesoftreatmentofindirectbilirubinaemia, except","o":["Phenobarbitone","Antibiotics","Phototherapy","Exchangetransfusion"],"ol":["A","B","C","D"],"k":1,"ex":"The principal treatments for clinically significant unconjugated neonatal hyperbilirubinemia are phototherapy and, when indicated by hour-specific thresholds and risk factors, exchange transfusion. Antibiotics are used only when infection is suspected or confirmed, not as bilirubin-lowering treatment. Phenobarbital has historical use as an enzyme inducer but is not routine first-line acute treatment in modern practice.","more":"The principal treatments for clinically significant unconjugated neonatal hyperbilirubinemia are phototherapy and, when indicated by hour-specific thresholds and risk factors, exchange transfusion. Antibiotics are used only when infection is suspected or confirmed, not as bilirubin-lowering treatment. Phenobarbital has historical use as an enzyme inducer but is not routine first-line acute treatment in modern practice.\n\nCurriculum alignment: Neonatology 2024–25, pp.49–51: phototherapy and exchange transfusion; pp.25–28: neonatal sepsis.\n\nHigh-yield point: Treatment thresholds depend on gestational age, postnatal age in hours and neurotoxicity risk factors; a fixed bilirubin number is unsafe. [AAP 2022 guideline](https://publications.aap.org/pediatrics/article/150/3/e2022058859/188549/).","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q37 — Treatment of indirect neonatal hyperbilirubinemia: exception","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 72 · printed page 124 · answer-key page 82 · original question 37.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q42","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Themanifestationoftherubellasyndromeinclude thefollowing,except","o":["Mentalretardation","Microcephaly","Cardiacdefects","Macrocephaly"],"ol":["A","B","C","D"],"k":3,"ex":"Congenital rubella can cause microcephaly, neurodevelopmental impairment, cataracts, hearing loss and congenital cardiac defects (especially PDA and pulmonary artery stenosis). Macrocephaly is not a typical feature, making it the exception.","more":"Congenital rubella can cause microcephaly, neurodevelopmental impairment, cataracts, hearing loss and congenital cardiac defects (especially PDA and pulmonary artery stenosis). Macrocephaly is not a typical feature, making it the exception.\n\nCurriculum alignment: Infectious 2024, pp.3–4: congenital rubella syndrome; Neonatology 2024–25, pp.27–28: TORCH and congenital infection.\n\nHigh-yield point: The classic CRS pattern includes eye, ear and heart involvement.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q42 — Congenital rubella syndrome: exception","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 73 · printed page 125 · answer-key page 83 · original question 42.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q48","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Theearlysymptomsoftheneonatalsepsis,except","o":["Lethargy","Fever","poorfeeding","Bleeding"],"ol":["A","B","C","D"],"k":3,"ex":"Neonatal sepsis often presents nonspecifically with lethargy, poor feeding, temperature instability, respiratory distress, apnea or irritability. Fever may occur but is not always present. Bleeding is more often a later sign associated with severe sepsis, thrombocytopenia or DIC, making it the likely exception.","more":"Neonatal sepsis often presents nonspecifically with lethargy, poor feeding, temperature instability, respiratory distress, apnea or irritability. Fever may occur but is not always present. Bleeding is more often a later sign associated with severe sepsis, thrombocytopenia or DIC, making it the likely exception.\n\nCurriculum alignment: Neonatology 2024–25, pp.25–28: neonatal sepsis, early signs and workup.\n\nHigh-yield point: A sick neonate may be hypothermic rather than febrile; absence of fever does not exclude sepsis.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q48 — Early symptom of neonatal sepsis: exception","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 73 · printed page 125 · answer-key page 83 · original question 48.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q53","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Themalformationassociatedwithpolyhydromnios except","o":["Anencephaly","Oesophagealatresia","Lunganomalies","Renalanomalies"],"ol":["A","B","C","D"],"k":3,"ex":"Polyhydramnios is associated with impaired fetal swallowing or gastrointestinal obstruction (e.g., anencephaly and esophageal atresia). Renal anomalies that reduce fetal urine production more often cause oligohydramnios, so “renal anomalies” is the intended exception, although not every renal anomaly reduces fluid.","more":"Polyhydramnios is associated with impaired fetal swallowing or gastrointestinal obstruction (e.g., anencephaly and esophageal atresia). Renal anomalies that reduce fetal urine production more often cause oligohydramnios, so “renal anomalies” is the intended exception, although not every renal anomaly reduces fluid.\n\nCurriculum alignment: Neonatology 2024–25, p.23: IUGR and pregnancy-related context; prenatal congenital anomaly differential.\n\nHigh-yield point: Polyhydramnios often suggests impaired swallowing or increased fetal urine production.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q53 — Malformation associated with polyhydramnios: exception","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 73 · printed page 125 · answer-key page 82 · original question 53.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q65","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Birth injury","q":"Morefrequentlyfracturedboneatbirth","o":["Cervicalvertebra","Humerus","Clavicle","Rib"],"ol":["A","B","C","D"],"k":2,"ex":"The clavicle is the most commonly fractured bone during childbirth, especially with shoulder dystocia or difficult delivery. Many fractures are greenstick or nondisplaced and heal with conservative care.","more":"The clavicle is the most commonly fractured bone during childbirth, especially with shoulder dystocia or difficult delivery. Many fractures are greenstick or nondisplaced and heal with conservative care.\n\nCurriculum alignment: Neonatology 2024–25, pp.40–42: birth injuries and clavicle fracture.\n\nHigh-yield point: An asymmetric Moro reflex, crepitus or pseudoparalysis may suggest clavicular fracture.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q65 — Most frequently fractured bone during birth","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 74 · printed page 126 · answer-key page 82 · original question 65.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q66","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Physiologicaljaundiceusuallyappearon......theday regresseson","o":["Firstdayandthirdday","Thirddayandninthday","Thirddayandseventhday","Ninthdayandeleventhday"],"ol":["A","B","C","D"],"k":2,"ex":"Physiological jaundice in term newborns usually becomes visible after the first 24 hours, often peaks around days 3–5, and then declines over the next several days. It should not be present in the first 24 hours. A traditional examination range is appearance around day 3 with resolution by about day 7 in term infants, but actual timing varies.","more":"Physiological jaundice in term newborns usually becomes visible after the first 24 hours, often peaks around days 3–5, and then declines over the next several days. It should not be present in the first 24 hours. A traditional examination range is appearance around day 3 with resolution by about day 7 in term infants, but actual timing varies.\n\nCurriculum alignment: Neonatology 2024–25, pp.43–45: neonatal jaundice, physiologic pattern and course.\n\nHigh-yield point: Jaundice in the first 24 hours is pathological until proven otherwise.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q66 — Typical timing of physiological neonatal jaundice","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 74 · printed page 126 · answer-key page 82 · original question 66.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q71","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Neurologic assessment","q":"Theimportantreflexnecessaryforbreastfeeds","o":["Moro'sreflex","Graspreflex","Rootingreflex","Coughreflex"],"ol":["A","B","C","D"],"k":2,"ex":"The rooting reflex is elicited by touching the cheek or corner of the mouth and causes the infant to turn toward the stimulus and open the mouth. It helps the infant locate the nipple and initiate feeding; sucking and swallowing then coordinate milk transfer.","more":"The rooting reflex is elicited by touching the cheek or corner of the mouth and causes the infant to turn toward the stimulus and open the mouth. It helps the infant locate the nipple and initiate feeding; sucking and swallowing then coordinate milk transfer.\n\nCurriculum alignment: Neonatology 2024–25, p.66: primitive reflexes; Growth and Nutrition 2024, pp.30–32: breastfeeding.\n\nHigh-yield point: Effective feeding requires coordinated rooting, latch, sucking, swallowing and breathing.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q71 — Primitive reflex supporting initiation of breastfeeding","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 74 · printed page 126 · answer-key page 82 · original question 71.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q75","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Riskofkernicterusisincreasedinall,except","o":["Lowlevelofserumalbumin","Acidosis","Prematurity","Highlevelofserumalbumin"],"ol":["A","B","C","D"],"k":3,"ex":"Low serum albumin, acidosis, prematurity, hemolysis, sepsis and clinical instability increase bilirubin neurotoxicity risk. High albumin provides more binding capacity and is not a risk factor; therefore it is the exception.","more":"Low serum albumin, acidosis, prematurity, hemolysis, sepsis and clinical instability increase bilirubin neurotoxicity risk. High albumin provides more binding capacity and is not a risk factor; therefore it is the exception.\n\nCurriculum alignment: Neonatology 2024–25, pp.43–51: bilirubin binding and kernicterus risk factors; AAP 2022 guideline identifies albumin <3 g/dL as a neurotoxicity risk factor.\n\nHigh-yield point: Low albumin increases the unbound bilirubin fraction; clinical instability and sepsis lower treatment thresholds.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q75 — Factor that does not increase kernicterus risk","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 75 · printed page 127 · answer-key page 82 · original question 75.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q84","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Management","q":"Inaninfantwithgalactocemia....shouldbeavoided of","o":["Gluten","Milk","Egg","Rice"],"ol":["A","B","C","D"],"k":1,"ex":"Classic galactosemia is usually due to GALT deficiency, causing accumulation of galactose-1-phosphate and toxic metabolites. Lactose-containing milk and dairy products must be excluded, with a suitable lactose/galactose-free formula.","more":"Classic galactosemia is usually due to GALT deficiency, causing accumulation of galactose-1-phosphate and toxic metabolites. Lactose-containing milk and dairy products must be excluded, with a suitable lactose/galactose-free formula.\n\nCurriculum alignment: Neonatology 2024–25: metabolic disorders and feeding; Endocrine 2025: metabolic/endocrine differential.\n\nHigh-yield point: Classic galactosemia is a medical emergency in a newborn with poor feeding, jaundice, liver dysfunction or E. coli sepsis.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q84 — Food that must be avoided in galactosemia","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 75 · printed page 127 · answer-key page 82 · original question 84.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q85","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Inkernicterusthefollowingisincreased","o":["Conjugatedbilurubin","Both","Unconjugatedbilurubin","None"],"ol":["A","B","C","D"],"k":2,"ex":"Kernicterus results from deposition of unconjugated bilirubin in brain tissue. Conjugated bilirubin is water-soluble and does not produce classic bilirubin encephalopathy.","more":"Kernicterus results from deposition of unconjugated bilirubin in brain tissue. Conjugated bilirubin is water-soluble and does not produce classic bilirubin encephalopathy.\n\nCurriculum alignment: Neonatology 2024–25, pp.43–51: indirect hyperbilirubinemia and kernicterus.\n\nHigh-yield point: Unconjugated bilirubin can cross the immature blood–brain barrier, especially when unbound.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q85 — Bilirubin fraction increased in kernicterus","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 75 · printed page 127 · answer-key page 82 · original question 85.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q86","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Cretinismischaracterizedbyall,except","o":["Mentalretardation","Hyperpyrexia","Macroglossia","Dwarfism"],"ol":["A","B","C","D"],"k":1,"ex":"Untreated congenital hypothyroidism can cause impaired neurodevelopment, poor linear growth, prolonged jaundice, hypotonia, macroglossia, large fontanelles and feeding difficulty. Hyperpyrexia is not a characteristic feature; affected infants may instead have hypothermia or temperature instability.","more":"Untreated congenital hypothyroidism can cause impaired neurodevelopment, poor linear growth, prolonged jaundice, hypotonia, macroglossia, large fontanelles and feeding difficulty. Hyperpyrexia is not a characteristic feature; affected infants may instead have hypothermia or temperature instability.\n\nCurriculum alignment: Endocrine 2025: congenital hypothyroidism; Neonatology 2024–25: newborn screening and clinical features.\n\nHigh-yield point: Early newborn screening and prompt levothyroxine treatment prevent severe intellectual disability.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q86 — Cretinism/congenital hypothyroidism: exception","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 76 · printed page 128 · answer-key page 82 · original question 86.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q101","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Other","q":"Thefollowingisthehighriskinfant","o":["Lessthan1500gm","Lessthan37weeks","Previousneonataldeath","All"],"ol":["A","B","C","D"],"k":3,"ex":"An infant with birthweight below 1500 g, gestational age below 37 weeks, or a history of previous neonatal death is at increased risk and requires closer follow-up. These are different indicators, and “all of the above” is the intended answer.","more":"An infant with birthweight below 1500 g, gestational age below 37 weeks, or a history of previous neonatal death is at increased risk and requires closer follow-up. These are different indicators, and “all of the above” is the intended answer.\n\nCurriculum alignment: Neonatology 2024–25, pp.14–21: prematurity; pp.22–24: IUGR; neonatal follow-up and risk categories.\n\nHigh-yield point: High-risk follow-up should assess growth, feeding, hearing, vision and neurodevelopment.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q101 — Definition of a high-risk infant","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 76 · printed page 128 · answer-key page 83 · original question 101.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q117","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Inkernicterus,thestainingofthebrainismoreintense in","o":["Spinalcord","Basalganglion","Corpuscollosum","Cerebralcortex"],"ol":["A","B","C","D"],"k":1,"ex":"Unconjugated bilirubin classically deposits in the basal ganglia, especially the globus pallidus and subthalamic nuclei, and in selected brainstem nuclei. This underlies the characteristic movement disorder and auditory/oculomotor abnormalities.","more":"Unconjugated bilirubin classically deposits in the basal ganglia, especially the globus pallidus and subthalamic nuclei, and in selected brainstem nuclei. This underlies the characteristic movement disorder and auditory/oculomotor abnormalities.\n\nCurriculum alignment: Neonatology 2024–25, p.51: bilirubin encephalopathy and kernicterus.\n\nHigh-yield point: Basal ganglia injury is central to chronic bilirubin encephalopathy.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q117 — Brain region with prominent staining in kernicterus","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 77 · printed page 129 · answer-key page 83 · original question 117.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q123","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Assessment","q":"Atbirthnormalheartrateis","o":["60-80","70-120","80-110","110-150"],"ol":["A","B","C","D"],"k":3,"ex":"A healthy term newborn’s heart rate is commonly around 100–160 beats per minute, with a higher rate during crying and a lower rate during sleep. The option 110–150 is a reasonable traditional range for the question. During resuscitation, heart rate is used to assess response and guide interventions.","more":"A healthy term newborn’s heart rate is commonly around 100–160 beats per minute, with a higher rate during crying and a lower rate during sleep. The option 110–150 is a reasonable traditional range for the question. During resuscitation, heart rate is used to assess response and guide interventions.\n\nCurriculum alignment: Neonatology 2024–25, pp.6 and 11–13: newborn examination and resuscitation assessment.\n\nHigh-yield point: A heart rate below 100/min in a non-vigorous newborn is a key threshold in neonatal resuscitation.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q123 — Normal heart rate at birth","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 78 · printed page 130 · answer-key page 82 · original question 123.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q130","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Definition","q":"Neonatalperiodextendsupto","o":["21daysoflife","28daysoflife","30daysoflife","35daysoflife"],"ol":["A","B","C","D"],"k":1,"ex":"The neonatal period is the first 28 completed days after birth. It is often divided into early neonatal (birth through day 7) and late neonatal (day 7 to day 28) periods.","more":"The neonatal period is the first 28 completed days after birth. It is often divided into early neonatal (birth through day 7) and late neonatal (day 7 to day 28) periods.\n\nCurriculum alignment: Neonatology 2024–25, p.3: neonatal period definition.\n\nHigh-yield point: The neonatal period is defined by age after birth, not gestational age.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q130 — Definition of the neonatal period","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 79 · printed page 131 · answer-key page 82 · original question 130.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q134","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Neurologic assessment","q":"Normalreflexpatternsatbirthmayinclude","o":["Graspreflex","Rootingreflex","Moro'sreflex","Alloftheabove"],"ol":["A","B","C","D"],"k":3,"ex":"Newborns normally demonstrate primitive reflexes including palmar grasp, rooting and Moro. These reflexes are mediated by subcortical pathways and gradually integrate as the nervous system matures.","more":"Newborns normally demonstrate primitive reflexes including palmar grasp, rooting and Moro. These reflexes are mediated by subcortical pathways and gradually integrate as the nervous system matures.\n\nCurriculum alignment: Neonatology 2024–25, p.66: primitive reflexes and significance.\n\nHigh-yield point: Assess primitive reflexes for presence, symmetry and appropriate integration with age.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q134 — Primitive reflexes normally present at birth","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 79 · printed page 131 · answer-key page 82 · original question 134.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q135","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Allarethefeaturesofthecaputsuccedenum except","o":["Crossesmidline","Doesnotdisappearwithin2-3days","Crossesthesutureline","Isdiffuseedematousswelling"],"ol":["A","B","C","D"],"k":1,"ex":"Caput succedaneum is diffuse subcutaneous edema of the presenting scalp part. It crosses suture lines and midline and usually resolves within 2–3 days. Persistence beyond this period is not typical and should prompt reconsideration of the diagnosis or assessment for another scalp lesion.","more":"Caput succedaneum is diffuse subcutaneous edema of the presenting scalp part. It crosses suture lines and midline and usually resolves within 2–3 days. Persistence beyond this period is not typical and should prompt reconsideration of the diagnosis or assessment for another scalp lesion.\n\nCurriculum alignment: Neonatology 2024–25, pp.5 and 40–42: newborn examination and birth injuries/scalp swelling.\n\nHigh-yield point: Caput crosses sutures; cephalohematoma is subperiosteal and does not cross sutures.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q135 — Caput succedaneum: feature that is not characteristic","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 79 · printed page 131 · answer-key page 82 · original question 135.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q138","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Complications","q":"Allareriskfactorsforthedevelopmentofthe deafnessexcept","o":["Birthasphyxia","Congenitalinfection","Bacterialmeningitis","Directhyperbilirubinemia"],"ol":["A","B","C","D"],"k":3,"ex":"Birth asphyxia, congenital infection and bacterial meningitis are recognized risk factors for hearing impairment. Unconjugated bilirubin neurotoxicity can damage auditory pathways; isolated direct (conjugated) hyperbilirubinemia is not the classic cause of kernicterus-associated auditory neuropathy.","more":"Birth asphyxia, congenital infection and bacterial meningitis are recognized risk factors for hearing impairment. Unconjugated bilirubin neurotoxicity can damage auditory pathways; isolated direct (conjugated) hyperbilirubinemia is not the classic cause of kernicterus-associated auditory neuropathy.\n\nCurriculum alignment: Neonatology 2024–25, pp.27–28 (congenital infections), pp.51 (kernicterus), pp.55–59 (asphyxia/HIE).\n\nHigh-yield point: Unconjugated bilirubin can damage the auditory brainstem and cause auditory neuropathy.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q138 — Risk factor for neonatal deafness: exception","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 80 · printed page 132 · answer-key page 82 · original question 138.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q139","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"Jaundiceinnewbornseenafter48hrwithbilirubin notexceeding5mg%is","o":["ABOincompatibility","Neonatalhepatitis","Haemolyticdiseaseofnewborn","Physiologicaljaundice"],"ol":["A","B","C","D"],"k":3,"ex":"Physiological jaundice generally appears after the first 24 hours, peaks over the next few days and then resolves. A jaundice onset after 48 hours with a low bilirubin value is compatible with physiological jaundice, provided the infant is otherwise well and the bilirubin pattern is appropriate for age in hours.","more":"Physiological jaundice generally appears after the first 24 hours, peaks over the next few days and then resolves. A jaundice onset after 48 hours with a low bilirubin value is compatible with physiological jaundice, provided the infant is otherwise well and the bilirubin pattern is appropriate for age in hours.\n\nCurriculum alignment: Neonatology 2024–25, pp.43–45: physiological jaundice timing and course.\n\nHigh-yield point: Early-onset jaundice (first 24 hours), rapid bilirubin rise or illness requires evaluation for pathology.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q139 — Newborn jaundice after 48 hours with low bilirubin level","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 80 · printed page 132 · answer-key page 82 · original question 139.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q141","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Allareresponsibleforindirecthyperbilirubinemia except","o":["Drugs","Hypothyroidism","Cephalhaematoma","Choledochalcyst"],"ol":["A","B","C","D"],"k":3,"ex":"Drugs, hypothyroidism and cephalohematoma can cause or contribute to unconjugated hyperbilirubinemia. A choledochal cyst causes extrahepatic biliary obstruction and typically produces conjugated (direct) hyperbilirubinemia/cholestasis, so it is the exception.","more":"Drugs, hypothyroidism and cephalohematoma can cause or contribute to unconjugated hyperbilirubinemia. A choledochal cyst causes extrahepatic biliary obstruction and typically produces conjugated (direct) hyperbilirubinemia/cholestasis, so it is the exception.\n\nCurriculum alignment: Neonatology 2024–25, pp.43–54: indirect jaundice and conjugated hyperbilirubinemia/biliary disorders; Endocrine 2025: hypothyroidism.\n\nHigh-yield point: Always fractionate bilirubin in prolonged jaundice; direct hyperbilirubinemia is never considered physiological.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q141 — Cause not responsible for indirect hyperbilirubinemia","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 80 · printed page 132 · answer-key page 82 · original question 141.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q162","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Management","q":"NewbornofHbsAg+vemothershouldbemanaged with","o":["HepatitisBactiveandpassive","HepatitisBactiveimmunization","Natreatment","Stopbreastfeeding 40 d 100 b 152 a 42 d 101 d 154 c 45 d 103 b 162 a 46 a 104 a 48 d 105 b 49 a 112 c 50 a 117 b"],"ol":["A","B","C","D"],"k":0,"ex":"The infant should receive hepatitis B vaccine (active immunization) and hepatitis B immune globulin (HBIG, passive immunization) as soon as possible after birth, ideally within 12 hours, at separate injection sites. Breastfeeding may continue after appropriate prophylaxis.","more":"The infant should receive hepatitis B vaccine (active immunization) and hepatitis B immune globulin (HBIG, passive immunization) as soon as possible after birth, ideally within 12 hours, at separate injection sites. Breastfeeding may continue after appropriate prophylaxis.\n\nCurriculum alignment: Pediatric vaccination, p.8 explicitly states HepB vaccine plus HBIG at birth; Neonatology 2024–25, pp.25–28 and TORCH/perinatal infection content. Current CDC guidance: [Perinatal Hepatitis B](https://www.cdc.gov/hepatitis-b/hcp/perinatal-provider-overview/).\n\nHigh-yield point: Give both products promptly; vaccine alone is not adequate prophylaxis for an infant of an HBsAg-positive mother.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q162 — Management of a newborn of an HBsAg-positive mother","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 82 · printed page 134 · answer-key page 83 · original question 162.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q3","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Diagnosis","q":"CausesoftheLGAbabies","o":["Infantsofthediabeticmother (bHydropsfoetalis","Noneoftheabove","Alloftheabove"],"ol":["A","C","D"],"k":2,"ex":"Infants of diabetic mothers commonly develop fetal hyperinsulinemia and macrosomia. Hydrops fetalis can also increase apparent birthweight through generalized edema. The source key selects “all of the above”; however, the stem’s options include a negative/None choice and the term “causes” is broad.","more":"Infants of diabetic mothers commonly develop fetal hyperinsulinemia and macrosomia. Hydrops fetalis can also increase apparent birthweight through generalized edema. The source key selects “all of the above”; however, the stem’s options include a negative/None choice and the term “causes” is broad.\n\nCurriculum alignment: Neonatology 2024–25, pp.38–39: infant of diabetic mother; pp.22–24: fetal growth and hydrops-related considerations.\n\nHigh-yield point: Maternal hyperglycemia drives fetal hyperinsulinemia and excess growth; after birth the infant is at risk of hypoglycemia.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q3 — Causes of a large-for-gestational-age infant","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 70 · printed page 122 · answer-key page 82 · original question 3.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q20","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Nutrition","q":"The following nutritionaldeficiencyare seen in breastfedinfants","o":["VitaminD","Iron","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Human milk has relatively low vitamin D unless the mother or infant receives supplementation, and iron stores in the infant eventually decline. The timing of iron deficiency depends on gestational age, birthweight, maternal iron status and feeding; healthy term infants usually have iron stores for the first several months. Thus both vitamin D and iron deficiency can occur, but they are not equally immediate or inevitable.","more":"Human milk has relatively low vitamin D unless the mother or infant receives supplementation, and iron stores in the infant eventually decline. The timing of iron deficiency depends on gestational age, birthweight, maternal iron status and feeding; healthy term infants usually have iron stores for the first several months. Thus both vitamin D and iron deficiency can occur, but they are not equally immediate or inevitable.\n\nCurriculum alignment: Growth and Nutrition 2024, pp.30–32: breastfeeding and milk composition; Neonatology 2024–25: feeding and nutrition.\n\nHigh-yield point: Exclusive breastfeeding is recommended, with age-appropriate vitamin D supplementation and iron guidance based on infant risk and local policy.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q20 — Nutritional deficiencies possible in exclusively breastfed infants","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 71 · printed page 123 · answer-key page 82 · original question 20.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q31","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Complications","q":"The long-term sequelae ofthe oxygen toxicity includes","o":["Retrolentalfibroplasia","Bronchopulmonarydysplasia","Both","None"],"ol":["A","B","C","D"],"k":2,"ex":"Excessive oxygen exposure in premature infants contributes to retinopathy of prematurity (historically called retrolental fibroplasia) and may contribute to bronchopulmonary dysplasia in the setting of lung immaturity, inflammation and ventilation injury. Both are recognized complications; the causal pathway is multifactorial, not oxygen alone.","more":"Excessive oxygen exposure in premature infants contributes to retinopathy of prematurity (historically called retrolental fibroplasia) and may contribute to bronchopulmonary dysplasia in the setting of lung immaturity, inflammation and ventilation injury. Both are recognized complications; the causal pathway is multifactorial, not oxygen alone.\n\nCurriculum alignment: Neonatology 2024–25, pp.15–21: RDS, oxygen therapy and bronchopulmonary dysplasia; ophthalmic screening in preterm infants.\n\nHigh-yield point: Use oxygen targets appropriate to gestational age and clinical condition to reduce both hypoxia and hyperoxia.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q31 — Long-term consequences of oxygen toxicity in premature infants","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 72 · printed page 124 · answer-key page 82 · original question 31.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q34","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"Rh-positivebabyborntoRh-negativemothermay notdeveloperythroblastosisin","o":["Firstchild","Secondchild","None","Both"],"ol":["A","B","C","D"],"k":0,"ex":"The first Rh-positive pregnancy is often unaffected if the Rh-negative mother has not previously been sensitized, because clinically significant anti-D IgG usually develops after fetal red cells enter maternal circulation. This is not guaranteed: prior pregnancy, transfusion or sensitization can affect the first recognized pregnancy.","more":"The first Rh-positive pregnancy is often unaffected if the Rh-negative mother has not previously been sensitized, because clinically significant anti-D IgG usually develops after fetal red cells enter maternal circulation. This is not guaranteed: prior pregnancy, transfusion or sensitization can affect the first recognized pregnancy.\n\nCurriculum alignment: Neonatology 2024–25, pp.46–47: Rh incompatibility, pathophysiology and prevention.\n\nHigh-yield point: Anti-D immunoglobulin prophylaxis prevents maternal sensitization; it is not treatment for an already sensitized mother.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q34 — Rh-positive infant of an Rh-negative mother who does not develop erythroblastosis","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 72 · printed page 124 · answer-key page 82 · original question 34.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q40","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Infectious disease","q":"Thebacterialinfectionstransmittedtofetusduring pregnancy","o":["Tuberculosis","Listeriamonocytogenes","Syphilis","Alloftheabove"],"ol":["A","B","C","D"],"k":3,"ex":"Maternal tuberculosis, Listeria monocytogenes and syphilis can cause fetal or congenital infection, though transmission mechanisms and timing differ. Listeria and syphilis can cross the placenta; congenital TB is uncommon but recognized.","more":"Maternal tuberculosis, Listeria monocytogenes and syphilis can cause fetal or congenital infection, though transmission mechanisms and timing differ. Listeria and syphilis can cross the placenta; congenital TB is uncommon but recognized.\n\nCurriculum alignment: Neonatology 2024–25, pp.25–28: congenital infection/TORCH and sepsis; Infectious 2024: bacterial disease.\n\nHigh-yield point: Maternal infection history, placental findings and neonatal examination guide evaluation for congenital infection.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q40 — Bacterial infections capable of being transmitted to the fetus during pregnancy","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 73 · printed page 125 · answer-key page 83 · original question 40.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q73","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Developmental milestone","q":"Headcontrolispossibleinaninfantby.....months","o":["1","3","5","6"],"ol":["A","B","C","D"],"k":1,"ex":"Head control develops over the first months. By about 3–4 months, most infants have substantially improved head control; the exact milestone depends on whether the question means head lag on pull-to-sit, prone head lifting or steady head control when held upright. Three months is the traditional exam answer, but the phrase is broad.","more":"Head control develops over the first months. By about 3–4 months, most infants have substantially improved head control; the exact milestone depends on whether the question means head lag on pull-to-sit, prone head lifting or steady head control when held upright. Three months is the traditional exam answer, but the phrase is broad.\n\nCurriculum alignment: Developmental milestones summary and Neonatology 2024–25: newborn neurological examination and primitive reflexes; age-specific developmental assessment.\n\nHigh-yield point: Always specify the position and task when documenting head control.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q73 — Age at which head control is usually achieved","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 75 · printed page 127 · answer-key page 82 · original question 73.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q100","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Clinical Case","q":"Thefollowingoccurininfantofdiabeticmother except","o":["Hypoglycaemia","Growthretardation","Hypocalcemia","Hyperbilirubinemia"],"ol":["A","B","C","D"],"k":1,"ex":"Infants of diabetic mothers are at risk of macrosomia, neonatal hypoglycemia, hypocalcemia, polycythemia and hyperbilirubinemia. Fetal growth restriction may occur in maternal vascular disease or longstanding complicated diabetes, so “growth retardation” is not impossible; it is simply not the classic pattern in an otherwise uncomplicated poorly controlled diabetic pregnancy.","more":"Infants of diabetic mothers are at risk of macrosomia, neonatal hypoglycemia, hypocalcemia, polycythemia and hyperbilirubinemia. Fetal growth restriction may occur in maternal vascular disease or longstanding complicated diabetes, so “growth retardation” is not impossible; it is simply not the classic pattern in an otherwise uncomplicated poorly controlled diabetic pregnancy.\n\nCurriculum alignment: Neonatology 2024–25, pp.38–39: infant of diabetic mother, metabolic and growth complications.\n\nHigh-yield point: Maternal vascular disease can shift the growth pattern from macrosomia to fetal growth restriction.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q100 — Finding not expected in an infant of a diabetic mother","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 76 · printed page 128 · answer-key page 83 · original question 100.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q103","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Prognosis","q":"Allare associated with the bad prognosiswith neonatalseizuresexcept","o":["Hypoglycaemia","Hypocalcaemia","Meningitis","Cerebralhaemorrhage"],"ol":["A","B","C","D"],"k":1,"ex":"Prognosis after neonatal seizures depends on the underlying cause, EEG background, seizure burden, brain imaging and gestational age. Seizures associated with a reversible metabolic disturbance such as hypocalcemia may have a better outcome when corrected promptly than seizures due to meningitis, major cerebral hemorrhage or severe hypoxic injury. The source-key exception is therefore plausible, but the prognosis is not determined by etiology alone.","more":"Prognosis after neonatal seizures depends on the underlying cause, EEG background, seizure burden, brain imaging and gestational age. Seizures associated with a reversible metabolic disturbance such as hypocalcemia may have a better outcome when corrected promptly than seizures due to meningitis, major cerebral hemorrhage or severe hypoxic injury. The source-key exception is therefore plausible, but the prognosis is not determined by etiology alone.\n\nCurriculum alignment: Neonatology 2024–25, pp.55–59: perinatal asphyxia, HIE and neonatal seizures; CNS 2024: seizure assessment.\n\nHigh-yield point: Treat the cause, not just the seizure: glucose, calcium, electrolytes, infection and brain injury all require evaluation.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q103 — Neonatal seizure factor associated with relatively better prognosis","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 77 · printed page 129 · answer-key page 83 · original question 103.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q104","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Development","q":"Maximumdevelopmentofbrainoccursduring","o":["Infancy","Firsttrimesterofpregnancy","Adolescence","Schoolingyear"],"ol":["A","B","C","D"],"k":0,"ex":"Brain growth and synaptogenesis are rapid in late fetal life and especially during infancy and the first years after birth. Among the listed broad age groups, infancy is the best answer. The question uses “maximum development” loosely; there is no single developmental peak for every brain process.","more":"Brain growth and synaptogenesis are rapid in late fetal life and especially during infancy and the first years after birth. Among the listed broad age groups, infancy is the best answer. The question uses “maximum development” loosely; there is no single developmental peak for every brain process.\n\nCurriculum alignment: Neonatology 2024–25, pp.3–4: neonatal development; Developmental milestones and assessment sources.\n\nHigh-yield point: The first 1000 days are a particularly important period for brain growth, nutrition and developmental stimulation.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q104 — Period of maximum brain development","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 77 · printed page 129 · answer-key page 83 · original question 104.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q105","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Clinical Case","q":"A childbornwithmicrocephaly,choreoretinities andintracranialcalcification,thediagnosisis","o":["Congenitalsyphilis","Toxoplasmosis","Rubella","Trypanosomiasis"],"ol":["A","B","C","D"],"k":1,"ex":"The classic triad of congenital toxoplasmosis includes chorioretinitis, hydrocephalus (not microcephaly in the typical triad) and diffuse intracranial calcifications. Microcephaly with intracranial calcifications and chorioretinitis may also occur with congenital CMV. Since CMV is not among the options and the stem says microcephaly, the classic triad is partly mismatched; toxoplasmosis is likely the intended answer but the stem needs qualification.","more":"The classic triad of congenital toxoplasmosis includes chorioretinitis, hydrocephalus (not microcephaly in the typical triad) and diffuse intracranial calcifications. Microcephaly with intracranial calcifications and chorioretinitis may also occur with congenital CMV. Since CMV is not among the options and the stem says microcephaly, the classic triad is partly mismatched; toxoplasmosis is likely the intended answer but the stem needs qualification.\n\nCurriculum alignment: Neonatology 2024–25, pp.27–28: TORCH infections; Infectious 2024: toxoplasmosis and congenital infection.\n\nHigh-yield point: Congenital CMV classically causes periventricular calcifications and microcephaly; toxoplasmosis classically causes diffuse calcifications and hydrocephalus.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q105 — Congenital infection suggested by microcephaly, chorioretinitis and intracranial calcification","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 77 · printed page 129 · answer-key page 83 · original question 105.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q112","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Neonataljaundicepersisting2weeksafterbirthis notseenin","o":["Galactosemia","Hypothyroidism","RHincompatibility","Breastmilkjaundice"],"ol":["A","B","C","D"],"k":2,"ex":"Breast-milk jaundice, congenital hypothyroidism and galactosemia can cause prolonged jaundice beyond two weeks. Rh isoimmune hemolysis usually presents early and is often recognized in the first days, although ongoing hemolysis can persist. Thus option c is the traditional expected answer, but prolonged jaundice in any infant requires evaluation rather than assuming a benign cause.","more":"Breast-milk jaundice, congenital hypothyroidism and galactosemia can cause prolonged jaundice beyond two weeks. Rh isoimmune hemolysis usually presents early and is often recognized in the first days, although ongoing hemolysis can persist. Thus option c is the traditional expected answer, but prolonged jaundice in any infant requires evaluation rather than assuming a benign cause.\n\nCurriculum alignment: Neonatology 2024–25, pp.43–45 and 48–52: jaundice patterns, breast-milk jaundice, hypothyroidism, metabolic disease and hemolysis.\n\nHigh-yield point: Jaundice persisting beyond 2 weeks in a term infant requires assessment including total and direct bilirubin.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q112 — Cause of prolonged neonatal jaundice not usually presenting after two weeks","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 77 · printed page 129 · answer-key page 83 · original question 112.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q122","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Clinical features","q":"Acutehyponatremiaproduceall,except","o":["Diarrhoea","Musclecrampsandweakness","Convulsions","Vascularcollapse"],"ol":["A","B","C","D"],"k":0,"ex":"Acute hyponatremia causes water movement into brain cells and may produce headache, nausea, confusion, seizures, coma and respiratory compromise. Muscle cramps and weakness can occur. Diarrhea is a common cause of sodium loss and hyponatremia, not a direct manifestation of the electrolyte disturbance itself.","more":"Acute hyponatremia causes water movement into brain cells and may produce headache, nausea, confusion, seizures, coma and respiratory compromise. Muscle cramps and weakness can occur. Diarrhea is a common cause of sodium loss and hyponatremia, not a direct manifestation of the electrolyte disturbance itself.\n\nCurriculum alignment: Neonatology 2024–25: metabolic/electrolyte problems; pediatric acute electrolyte disorders in clinical teaching.\n\nHigh-yield point: Severe symptomatic hyponatremia is an emergency; correction must be carefully controlled to avoid osmotic demyelination.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q122 — Manifestation not caused by acute hyponatremia","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 78 · printed page 130 · answer-key page 82 · original question 122.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q127","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Complications","q":"Hazardsofexchangetransfusionincludeall,except","o":["Oligaemicshock","Cardiacarrest","Citratetetany","Atrialflutter"],"ol":["A","B","C","D"],"k":3,"ex":"Exchange transfusion can cause volume instability, hypocalcemia/citrate toxicity, thrombocytopenia, electrolyte disturbances, arrhythmia, infection and catheter-related complications. Atrial flutter is not a classic expected complication, so it is the intended exception.","more":"Exchange transfusion can cause volume instability, hypocalcemia/citrate toxicity, thrombocytopenia, electrolyte disturbances, arrhythmia, infection and catheter-related complications. Atrial flutter is not a classic expected complication, so it is the intended exception.\n\nCurriculum alignment: Neonatology 2024–25, pp.49–50: exchange transfusion indications and procedure.\n\nHigh-yield point: Exchange transfusion is a high-risk procedure performed with continuous monitoring and laboratory checks.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q127 — Complication of exchange transfusion: exception","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 78 · printed page 130 · answer-key page 82 · original question 127.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q132","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Investigation","q":"TheAPTtestis","o":["Crudetestforcarbonmonoxide","SemiquantitativetestforfoetalHb","Semiquantitativetestforleadpoisoning","ScreeningforhaemoglobinS"],"ol":["A","B","C","D"],"k":1,"ex":"The Apt (alkali denaturation) test distinguishes fetal hemoglobin from adult hemoglobin in blood, such as when assessing whether blood in a newborn’s vomit or stool is maternal or neonatal. Fetal hemoglobin resists alkali denaturation and remains pink; adult hemoglobin becomes yellow-brown.","more":"The Apt (alkali denaturation) test distinguishes fetal hemoglobin from adult hemoglobin in blood, such as when assessing whether blood in a newborn’s vomit or stool is maternal or neonatal. Fetal hemoglobin resists alkali denaturation and remains pink; adult hemoglobin becomes yellow-brown.\n\nCurriculum alignment: Neonatology 2024–25: newborn assessment and bleeding/hematologic differential; the test is an additional diagnostic application beyond the main course outline.\n\nHigh-yield point: The Apt test helps distinguish swallowed maternal blood from neonatal gastrointestinal bleeding.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q132 — Purpose of the Apt test","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 79 · printed page 131 · answer-key page 82 · original question 132.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q143","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Pathophysiology","q":"InasymmetricalIUGR,theorganisnotaffected","o":["Subcutaneousfat","Liver","Muscle","Brain"],"ol":["A","B","C","D"],"k":3,"ex":"Asymmetric fetal growth restriction usually follows a later placental insufficiency pattern in which blood flow is redistributed to preserve vital organs. The brain is relatively spared compared with liver, muscle and subcutaneous fat (“brain-sparing”), although neurodevelopmental risk remains.","more":"Asymmetric fetal growth restriction usually follows a later placental insufficiency pattern in which blood flow is redistributed to preserve vital organs. The brain is relatively spared compared with liver, muscle and subcutaneous fat (“brain-sparing”), although neurodevelopmental risk remains.\n\nCurriculum alignment: Neonatology 2024–25, pp.22–24: IUGR types and asymmetric growth pattern.\n\nHigh-yield point: Asymmetric IUGR often preserves head circumference more than abdominal circumference.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q143 — Organ relatively spared in asymmetrical IUGR","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 80 · printed page 132 · answer-key page 82 · original question 143.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-neonatology-accepted-Q152","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Differential Diagnosis","q":"Vomitingonthefirstdayinanewbornisdueto","o":["Amnioticfluidgastritis","Hydrocephalus","Pyloricstenosis","Congenitalmegacolon"],"ol":["A","B","C","D"],"k":0,"ex":"A small amount of mucus or swallowed amniotic fluid may cause transient early regurgitation in an otherwise well newborn. Persistent, bilious, projectile or associated vomiting requires evaluation for obstruction, infection, metabolic disease or raised intracranial pressure. Pyloric stenosis typically presents weeks later, not on day one.","more":"A small amount of mucus or swallowed amniotic fluid may cause transient early regurgitation in an otherwise well newborn. Persistent, bilious, projectile or associated vomiting requires evaluation for obstruction, infection, metabolic disease or raised intracranial pressure. Pyloric stenosis typically presents weeks later, not on day one.\n\nCurriculum alignment: Neonatology 2024–25, pp.5–7: newborn examination and delayed passage of meconium; GIT 2024–25: neonatal vomiting and obstruction differential.\n\nHigh-yield point: Bilious vomiting in a neonate is an emergency until intestinal obstruction/malrotation is excluded.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q152 — Cause of vomiting on the first day after birth","aoSource":"`MCQ د عرفة متقسم` · PDF-sequence page 81 · printed page 133 · answer-key page 83 · original question 152.","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Neonatology_Accepted.md","_genhy":false},{"id":"EB-paediatrics-preventive-and-social-medicine-accepted-Q13","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Neonatology / classification","q":"Verylowbirthweightreferstobirthweightlessthan","o":["Lessthan2kg","Lessthan2.5kg","Lessthan1.5kg","Lessthan1.8kg"],"ol":["A","B","C","D"],"k":2,"ex":"Very low birth weight (VLBW) is defined by an absolute birth weight below 1,500 g, irrespective of gestational age. This is distinct from small for gestational age (SGA), which is defined by a birth-weight centile below the 10th centile for gestational age.","more":"Very low birth weight (VLBW) is defined by an absolute birth weight below 1,500 g, irrespective of gestational age. This is distinct from small for gestational age (SGA), which is defined by a birth-weight centile below the 10th centile for gestational age. **Why the others are wrong:** (a) <2 kg: too high for VLBW. (b) <2.5 kg: this is the low-birth-weight threshold. (c) <1.5 kg: correct VLBW threshold. (d) <1.8 kg: not the standard definition.\n\nCurriculum alignment: Neonatology 2024–2025, p.3: birth-weight definitions.\n\nHigh-yield point: Do not confuse VLBW with LBW (<2,500 g) or ELBW (<1,000 g).","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q13 — Neonatology / classification","aoSource":"Question-bank MD p.151 · printed p.283 · answer-key PDF p.153 · original Q13","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Preventive_and_Social_Medicine_Accepted.md","_genhy":false},{"id":"EB-paediatrics-preventive-and-social-medicine-accepted-Q14","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Neonatology / classification","q":"Extremelylowbirthweightbabiesreferstothebirth weightlessthan","o":["1kg","800grams","1.2kg","1.5kg"],"ol":["A","B","C","D"],"k":0,"ex":"Extremely low birth weight (ELBW) is birth weight below 1,000 g (1 kg). This is an absolute weight category, not a gestational-age percentile.","more":"Extremely low birth weight (ELBW) is birth weight below 1,000 g (1 kg). This is an absolute weight category, not a gestational-age percentile. **Why the others are wrong:** (a) 1 kg: correct threshold. (b) 800 g: describes a narrower subset but is not the definition. (c) 1.2 kg: above the ELBW threshold. (d) 1.5 kg: VLBW threshold.\n\nCurriculum alignment: Neonatology 2024–2025, p.3: ELBW definition.\n\nHigh-yield point: Strictly, ELBW is <1,000 g; a baby weighing exactly 1,000 g is not below the cutoff.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q14 — Neonatology / classification","aoSource":"Question-bank MD p.151 · printed p.283 · answer-key PDF p.153 · original Q14","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Preventive_and_Social_Medicine_Accepted.md","_genhy":false},{"id":"EB-paediatrics-preventive-and-social-medicine-accepted-Q94","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Neonatology / immunoprophylaxis","q":"Theprophylacticuseofimmunoglobulinfornon- communicabledisease","o":["AntiRhDimmunoglobulin","Haemolyticanaemia","Both","None"],"ol":["A","B","C","D"],"k":0,"ex":"Anti-D immunoglobulin is administered to an unsensitized Rh-negative pregnant/postpartum patient to prevent maternal sensitization to Rh(D)-positive red cells. Preventing maternal anti-D formation reduces the risk of haemolytic disease of the fetus and newborn in a subsequent Rh-positive pregnancy. The option asks for prophylactic immunoglobulin in a non-infectious disease context; this is anti-D prophylaxis.","more":"Anti-D immunoglobulin is administered to an unsensitized Rh-negative pregnant/postpartum patient to prevent maternal sensitization to Rh(D)-positive red cells. Preventing maternal anti-D formation reduces the risk of haemolytic disease of the fetus and newborn in a subsequent Rh-positive pregnancy. The option asks for prophylactic immunoglobulin in a non-infectious disease context; this is anti-D prophylaxis. **Why the others are wrong:** (a) Anti-RhD immunoglobulin: correct; prevents Rh alloimmunization. (b) Haemolytic anaemia: a disease manifestation, not the immunoglobulin preparation. (c) Both: incorrect because b is not the prophylactic immunoglobulin. (d) None: incorrect.\n\nCurriculum alignment: Neonatology 2024–2025, pp.46–47: Rh incompatibility, prevention with anti-D immunoglobulin given to an Rh-negative mother carrying an Rh-positive fetus.\n\nHigh-yield point: Anti-D is preventive immunoprophylaxis; it is not a treatment for established fetal/neonatal haemolysis. ## EXTENDED ACCEPTED","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q94 — Neonatology / immunoprophylaxis","aoSource":"Question-bank MD p.153 · printed p.285 · answer-key PDF p.153 · original Q94","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Preventive_and_Social_Medicine_Accepted.md","_genhy":false},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q81","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Neonatology / primitive reflexes","q":"Moro'sreflexappearsby","o":["Birth","1month","2months","3months"],"ol":["A","B","C","D"],"k":0,"ex":"The Moro (startle) reflex is present in term newborns at birth. It is elicited by a sudden change in head position or a startling stimulus.","more":"The Moro (startle) reflex is present in term newborns at birth. It is elicited by a sudden change in head position or a startling stimulus. **Why the others are wrong:** (a) Birth: correct. (b) 1 month, (c) 2 months, (d) 3 months: all too late for its normal appearance in a term infant.\n\nCurriculum alignment: Neonatology 2024–2025: primitive reflexes and gestational-age assessment; Developmental milestones summary. **High-yield point / Review Notes:** Absence, asymmetry, or persistence beyond the expected integration period warrants assessment.\n\nHigh-yield point: The Moro (startle) reflex is present in term newborns at birth.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q81 — Neonatology / primitive reflexes","aoSource":"Question-bank MD p.160 · printed p.310 · answer-key PDF p.168 · original Q81","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q116","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Neonatology / skin findings","q":"Mongolianspotsareseenin","o":["Meningitis","Normalchild","Mentalretardation","Encephalitis"],"ol":["A","B","C","D"],"k":1,"ex":"Mongolian spots, now commonly called congenital dermal melanocytosis, are benign blue-grey macules caused by dermal melanocytes. They are commonly seen in otherwise healthy newborns and children and usually fade with age. They are not a marker of meningitis, encephalitis, or intellectual disability.","more":"Mongolian spots, now commonly called congenital dermal melanocytosis, are benign blue-grey macules caused by dermal melanocytes. They are commonly seen in otherwise healthy newborns and children and usually fade with age. They are not a marker of meningitis, encephalitis, or intellectual disability. **Why the others are wrong:** (a) Meningitis: not the expected association. (b) Normal child: correct; a benign normal variant. (c) Mental retardation: not an association. (d) Encephalitis: not an association.\n\nCurriculum alignment: Pediatric dermatology and neonatal examination: congenital dermal melanocytosis (Mongolian spots). **High-yield point / Review Notes:** Document location and appearance to distinguish congenital dermal melanocytosis from bruising; extensive or atypical lesions should be assessed in context.\n\nHigh-yield point: Mongolian spots, now commonly called congenital dermal melanocytosis, are benign blue-grey macules caused by dermal melanocytes.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q116 — Neonatology / skin findings","aoSource":"Question-bank MD p.162 · printed p.312 · answer-key PDF p.169 · original Q116","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q187","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Neonatology / birth trauma","q":"Thebonemostfrequentlyfracturedduringdelivery is","o":["Radius","Humerus","Clavicle","Unla"],"ol":["A","B","C","D"],"k":2,"ex":"The clavicle is the bone most commonly fractured during delivery. Risk is increased with shoulder dystocia, macrosomia and difficult vaginal delivery. Most neonatal clavicular fractures heal well with minimal intervention.","more":"The clavicle is the bone most commonly fractured during delivery. Risk is increased with shoulder dystocia, macrosomia and difficult vaginal delivery. Most neonatal clavicular fractures heal well with minimal intervention. **Why the others are wrong:** (a) Radius: uncommon birth fracture. (b) Humerus: can fracture during difficult delivery but less often than clavicle. (c) Clavicle: correct. (d) “Unla”: likely OCR/source misspelling of ulna; ulna fracture is not the commonest birth fracture.\n\nCurriculum alignment: Neonatology 2024–2025: birth injuries and neonatal examination. **High-yield point / Review Notes:** Look for crepitus, swelling, reduced movement/pseudoparalysis and asymmetric Moro reflex.\n\nHigh-yield point: The clavicle is the bone most commonly fractured during delivery.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q187 — Neonatology / birth trauma","aoSource":"Question-bank MD p.166 · printed p.316 · answer-key PDF p.169 · original Q187","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q216","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Neonatology / bronchopulmonary dysplasia","q":"All of the following are causes of bronchopulmonarydysplasia,except","o":["Oxygentoxicity","Theophyllinuse","Traumaticdamagetolungs","Pulmonaryedemaduetocapillaryleakage"],"ol":["A","B","C","D"],"k":1,"ex":"Bronchopulmonary dysplasia (BPD) is a chronic lung disease of prematurity associated with immature lungs, oxygen exposure, mechanical ventilation/barotrauma, inflammation and fluid overload/pulmonary oedema. Theophylline is a methylxanthine used historically to treat apnoea of prematurity; it is not an established cause of BPD.","more":"Bronchopulmonary dysplasia (BPD) is a chronic lung disease of prematurity associated with immature lungs, oxygen exposure, mechanical ventilation/barotrauma, inflammation and fluid overload/pulmonary oedema. Theophylline is a methylxanthine used historically to treat apnoea of prematurity; it is not an established cause of BPD. **Why the others are wrong:** (a) Oxygen toxicity: contributes to lung injury. (b) Theophylline use: correct exception; it is a treatment for apnoea, not a causal risk factor for BPD. (c) Traumatic lung damage: ventilation-related injury contributes. (d) Pulmonary oedema due to capillary leakage: contributes to lung injury and BPD pathogenesis.\n\nCurriculum alignment: Neonatology 2024–2025: prematurity, respiratory distress, oxygen exposure and chronic lung disease. **High-yield point / Review Notes:** Modern BPD is multifactorial; no single exposure alone explains the disease.\n\nHigh-yield point: Bronchopulmonary dysplasia (BPD) is a chronic lung disease of prematurity associated with immature lungs, oxygen exposure, mechanical ventilation/barotrauma, inflammation and fluid overload/pulmonary oedema.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q216 — Neonatology / bronchopulmonary dysplasia","aoSource":"Question-bank MD p.167 · printed p.317 · answer-key PDF p.169 · original Q216","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true},{"id":"EB-paediatrics-miscellaneous-topics-accepted-Q218","spec":"eb-neonatology","topic":0,"tag":"Egyptian book","kind":"Neonatology / apnoea definition","q":"Inachildcessationofbreathingin20secwith bradycardia","o":["Apnea","Cheyne-Stokesbreathing","Dyspnea","None"],"ol":["A","B","C","D"],"k":0,"ex":"Apnoea of prematurity is commonly defined as a pause in breathing lasting at least 20 seconds, or a shorter pause associated with bradycardia, cyanosis or oxygen desaturation. The stem describes a 20-second cessation with bradycardia, consistent with apnoea.","more":"Apnoea of prematurity is commonly defined as a pause in breathing lasting at least 20 seconds, or a shorter pause associated with bradycardia, cyanosis or oxygen desaturation. The stem describes a 20-second cessation with bradycardia, consistent with apnoea. **Why the others are wrong:** (a) Apnea: correct. (b) Cheyne–Stokes breathing: a cyclical waxing/waning pattern with periods of apnoea, not the simple event described. (c) Dyspnea: increased work or subjective difficulty breathing, not cessation. (d) None: incorrect.\n\nCurriculum alignment: Neonatology 2024–2025: neonatal apnea, respiratory distress and monitoring. **High-yield point / Review Notes:** Evaluate recurrent apnoea for prematurity, infection, metabolic disturbance, respiratory or neurological causes.\n\nHigh-yield point: Apnoea of prematurity is commonly defined as a pause in breathing lasting at least 20 seconds, or a shorter pause associated with bradycardia, cyanosis or oxygen desaturation.","ao":true,"eb":true,"aoClass":"Accepted","aoReview":false,"aoTitle":"Q218 — Neonatology / apnoea definition","aoSource":"Question-bank MD p.168 · printed p.318 · answer-key PDF p.169 · original Q218","aoSystem":"حديثو الولادة","aoPart":"","kx":false,"ebSourceFile":"Paediatrics_Miscellaneous_Topics_Accepted.md","_genhy":true}]);

